// {{{ Data collection
// Everything here comes out of Prometheus. The restic units themselves export
// nothing, so "did the backup run" is answered by the timer's last trigger
// rather than by asking restic -- n8n is DynamicUser-sandboxed and cannot
// shell out to `restic snapshots` even if it wanted to.
const PROM = 'http://127.0.0.1:8451/api/v1/query';

const query = async (expr) => {
  const res = await this.helpers.httpRequest({ method: 'GET', url: PROM, qs: { query: expr }, json: true });
  return res?.data?.result ?? [];
};

const BACKUP_SETS = [
  { unit: 'restic-backups-data', label: 'data', detail: '/persist/data -> raid5pool' },
  { unit: 'restic-backups-state', label: 'state', detail: '/persist/state -> raid5pool' },
  { unit: 'restic-backups-offsite', label: 'offsite', detail: 'photos+docs+db -> backblaze b2' },
];

// All three timers are OnCalendar=daily, so anything past ~30h has skipped a
// run and anything past ~50h has skipped two.
const STALE_WARN_HOURS = 30;
const STALE_CRIT_HOURS = 50;
const POOL_WARN_PCT = 80;
const POOL_CRIT_PCT = 90;

const [triggers, failed, poolHealth, poolSize, poolFree, poolFrag, datasetUsed, poolGrowth] = await Promise.all([
  query('node_systemd_timer_last_trigger_seconds{name=~"restic-backups-.*"}'),
  query('node_systemd_unit_state{name=~"restic-backups-.*\\\\.service",state="failed"}'),
  query('zfs_pool_health'),
  query('zfs_pool_size_bytes'),
  query('zfs_pool_free_bytes'),
  query('zfs_pool_fragmentation_ratio'),
  query('zfs_dataset_used_bytes{type="filesystem"}'),
  // Negative values are fine and meaningful: a pool that shrank had something
  // pruned or destroyed, which is worth seeing rather than clamping away.
  query('zfs_pool_allocated_bytes - (zfs_pool_allocated_bytes offset 7d)'),
]);

const num = (s) => Number(s.value[1]);
const byLabel = (series, key) => Object.fromEntries(series.map((s) => [s.metric[key], num(s)]));

const lastTrigger = byLabel(triggers, 'name');
const failedUnits = new Set(failed.filter((s) => num(s) === 1).map((s) => s.metric.name));
const health = byLabel(poolHealth, 'pool');
const size = byLabel(poolSize, 'pool');
const free = byLabel(poolFree, 'pool');
const frag = byLabel(poolFrag, 'pool');
const used = byLabel(datasetUsed, 'name');
const growth = byLabel(poolGrowth, 'pool');
// }}}

// {{{ Evaluation
const now = Date.now() / 1000;
const gib = (b) => `${(b / 1024 ** 3).toFixed(1)} GiB`;
const tib = (b) => `${(b / 1024 ** 4).toFixed(2)} TiB`;
const human = (b) => (Math.abs(b) >= 1024 ** 4 ? tib(b) : gib(b));

const age = (hours) => {
  if (hours < 1) return `${Math.round(hours * 60)}m ago`;
  if (hours < 48) return `${hours.toFixed(1)}h ago`;
  return `${Math.floor(hours / 24)}d ago`;
};

const sets = BACKUP_SETS.map((set) => {
  const ts = lastTrigger[`${set.unit}.timer`];
  const isFailed = failedUnits.has(`${set.unit}.service`);

  if (isFailed) return { ...set, value: 'FAILED', extra: ts ? age((now - ts) / 3600) : '', level: 'critical' };
  // A timer with no last-trigger metric has never fired since boot. That is
  // not the same as a failure, but it is not evidence of a backup either.
  if (ts === undefined) return { ...set, value: 'NEVER RAN', extra: 'no trigger since boot', level: 'critical' };

  const hours = (now - ts) / 3600;
  const level = hours >= STALE_CRIT_HOURS ? 'critical' : hours >= STALE_WARN_HOURS ? 'warn' : 'ok';
  return { ...set, value: age(hours), extra: level === 'ok' ? '' : 'skipped a run', level };
});

const pools = Object.keys(health).sort().map((pool) => {
  const total = size[pool];
  const avail = free[pool];
  const pct = total ? 100 * (1 - avail / total) : 0;
  const weekly = growth[pool] ?? 0;
  // Only extrapolate when the pool is actually growing; a flat or shrinking
  // pool has no meaningful date at which it fills up.
  const weeksToFull = weekly > 0 ? ((total * (POOL_CRIT_PCT / 100)) - (total - avail)) / weekly : null;

  return {
    pool,
    healthy: health[pool] === 0,
    pct,
    used: total - avail,
    total,
    frag: frag[pool],
    weekly,
    weeksToFull,
    level: health[pool] !== 0 ? 'critical' : pct >= POOL_CRIT_PCT ? 'critical' : pct >= POOL_WARN_PCT ? 'warn' : 'ok',
  };
});

const REPO_DATASET = 'raid5pool/backups';
const repoSize = used[REPO_DATASET];

const rows = [
  ...sets.map((s) => ({ label: `last run · ${s.label}`, value: s.value, detail: s.extra || s.detail, level: s.level })),
  {
    label: 'local repo size',
    value: repoSize === undefined ? 'unknown' : human(repoSize),
    detail: REPO_DATASET,
    level: repoSize === undefined ? 'warn' : 'ok',
  },
];

const poolRows = pools.map((p) => ({
  label: `${p.pool}`,
  value: `${p.pct.toFixed(1)}%`,
  detail: `${human(p.used)} / ${human(p.total)}${p.frag === undefined ? '' : ` · ${p.frag.toFixed(0)}% frag`}`,
  level: p.level,
}));

const growthRows = pools.map((p) => {
  const trend = p.weekly === 0 ? 'flat' : `${p.weekly > 0 ? '+' : '-'}${human(Math.abs(p.weekly))}/wk`;
  const forecast =
    p.weeksToFull === null
      ? 'no growth'
      : p.weeksToFull <= 0
        ? `already past ${POOL_CRIT_PCT}%`
        : p.weeksToFull < 104
          ? `~${Math.round(p.weeksToFull)}wk to ${POOL_CRIT_PCT}%`
          : '>2yr headroom';

  return {
    label: p.pool,
    value: trend,
    detail: forecast,
    level: p.weeksToFull !== null && p.weeksToFull > 0 && p.weeksToFull < 8 ? 'warn' : 'ok',
  };
});

const all = [...rows, ...poolRows, ...growthRows];
const overall = all.some((r) => r.level === 'critical') ? 'critical' : all.some((r) => r.level === 'warn') ? 'warn' : 'ok';
// }}}

// {{{ Rosé Pine Moon
// Same palette as every other digest from this instance, from the base16
// scheme the desktops use (rose-pine-moon.yaml, via
// common/themes/default.nix). Duplicated because n8n Code nodes cannot
// import; change one, change all five.
//
// Status meaning is fixed everywhere: foam is fine, gold wants a look, love
// wants an action. This digest is the ledger of the machine, so gold leads
// where health-monitor leads with iris -- same palette, different voice.
const rp = {
  base: '#232136',
  surface: '#2a273f',
  overlay: '#393552',
  muted: '#6e6a86',
  subtle: '#908caa',
  text: '#e0def4',
  love: '#eb6f92',
  gold: '#f6c177',
  rose: '#ea9a97',
  pine: '#3e8fb0',
  foam: '#9ccfd8',
  iris: '#c4a7e7',
  highlight: '#56526e',
};

const level = {ok: rp.foam, warn: rp.gold, critical: rp.love};
const tag = {ok: '[ OK ]', warn: '[WARN]', critical: '[CRIT]'};
const overallCopy = {
  ok: 'BACKUPS CURRENT',
  warn: 'BACKUPS NEED A LOOK',
  critical: 'BACKUPS AT RISK',
}[overall];
const mono = "ui-monospace,'JetBrains Mono','SFMono-Regular',Menlo,Consolas,'Liberation Mono',monospace";
const accent = level[overall];
// }}}

// {{{ Render
// Bars are two table cells, not a background image or a run of block glyphs:
// Outlook drops the first and mismeasures the second.
const gauge = (pct, colour) => {
  const filled = Math.max(1, Math.min(100, Math.round(pct)));
  return `<table role="presentation" width="100%" style="border-collapse:collapse;table-layout:fixed;">
    <tr>
      <td width="${filled}%" style="height:4px;line-height:4px;font-size:0;background:${colour};">&nbsp;</td>
      <td width="${100 - filled}%" style="height:4px;line-height:4px;font-size:0;background:${rp.overlay};">&nbsp;</td>
    </tr>
  </table>`;
};

const heading = (title, note) => `<tr>
  <td style="padding:22px 30px 2px 30px;">
    <table role="presentation" width="100%" style="border-collapse:collapse;">
      <tr>
        <td style="font-family:${mono};font-size:11px;letter-spacing:0.18em;color:${rp.gold};text-transform:uppercase;white-space:nowrap;">${title}</td>
        <td style="font-family:${mono};font-size:10px;color:${rp.muted};text-align:right;white-space:nowrap;">${note}</td>
      </tr>
    </table>
    <div style="border-top:1px solid ${rp.overlay};margin-top:8px;"></div>
  </td>
</tr>`;

// The three backup sets are the headline, so they are cards across the top
// rather than three more lines in a list: "when did each of these last run"
// is the single question this mail exists to answer.
const setCard = (s) => {
  const c = level[s.level];
  return `<td width="33%" style="padding:0 5px;vertical-align:top;">
    <table role="presentation" width="100%" style="border-collapse:collapse;background:${rp.base};border:1px solid ${rp.overlay};border-radius:6px;">
      <tr><td style="height:3px;line-height:3px;font-size:0;background:${c};">&nbsp;</td></tr>
      <tr>
        <td style="padding:12px 12px 13px 12px;">
          <div style="font-family:${mono};font-size:11px;letter-spacing:0.14em;color:${rp.subtle};text-transform:uppercase;">${s.label}</div>
          <div style="font-family:${mono};font-size:17px;color:${rp.text};margin-top:8px;white-space:nowrap;">${s.value}</div>
          <div style="font-family:${mono};font-size:10px;color:${c};font-weight:700;margin-top:7px;">${tag[s.level]}</div>
          <div style="font-family:${mono};font-size:9px;color:${rp.muted};margin-top:6px;line-height:1.4;">${s.extra || s.detail}</div>
        </td>
      </tr>
    </table>
  </td>`;
};

const poolPanel = pools
  .map((p) => {
    const c = level[p.level];
    const weekly = p.weekly === 0 ? 'flat' : `${p.weekly > 0 ? '+' : '−'}${human(Math.abs(p.weekly))}/wk`;
    const forecast =
      p.weeksToFull === null
        ? 'no growth'
        : p.weeksToFull <= 0
          ? `past ${POOL_CRIT_PCT}%`
          : p.weeksToFull < 104
            ? `~${Math.round(p.weeksToFull)} wk to ${POOL_CRIT_PCT}%`
            : '>2 yr headroom';
    // The forecast is the part worth reading twice, so it sits on the bar's
    // own line rather than in a detail column nobody scans.
    const soon = p.weeksToFull !== null && p.weeksToFull > 0 && p.weeksToFull < 26;

    return `<tr>
      <td style="padding:13px 30px 5px 30px;">
        <table role="presentation" width="100%" style="border-collapse:collapse;">
          <tr>
            <td style="font-family:${mono};font-size:14px;color:${rp.text};white-space:nowrap;">${p.pool}</td>
            <td style="font-family:${mono};font-size:14px;color:${rp.text};text-align:right;white-space:nowrap;">
              ${p.pct.toFixed(1)}%<span style="color:${c};font-weight:700;margin-left:12px;">${tag[p.level]}</span>
            </td>
          </tr>
        </table>
      </td>
    </tr>
    <tr><td style="padding:0 30px 6px 30px;">${gauge(p.pct, c)}</td></tr>
    <tr>
      <td style="padding:0 30px 12px 30px;">
        <table role="presentation" width="100%" style="border-collapse:collapse;">
          <tr>
            <td style="font-family:${mono};font-size:10px;color:${rp.muted};white-space:nowrap;">${human(p.used)} / ${human(p.total)}${p.frag === undefined ? '' : ` · ${p.frag.toFixed(0)}% frag`}</td>
            <td style="font-family:${mono};font-size:10px;color:${soon ? rp.gold : rp.muted};text-align:right;white-space:nowrap;">${weekly} · ${forecast}</td>
          </tr>
        </table>
      </td>
    </tr>`;
  })
  .join('\n');

const repoLine = `<tr>
  <td style="padding:12px 30px 16px 30px;">
    <table role="presentation" width="100%" style="border-collapse:collapse;">
      <tr>
        <td style="font-family:${mono};font-size:13px;color:${rp.subtle};white-space:nowrap;">local repo</td>
        <td style="font-family:${mono};font-size:13px;color:${rp.text};text-align:right;white-space:nowrap;">
          ${repoSize === undefined ? 'unknown' : human(repoSize)}
          <span style="color:${rp.muted};font-size:10px;"> ${REPO_DATASET}</span>
        </td>
      </tr>
    </table>
  </td>
</tr>`;

const timestamp = new Date().toLocaleString('en-GB', {timeZone: 'Europe/Berlin', dateStyle: 'medium', timeStyle: 'short'});

const html = `<!DOCTYPE html>
<html>
  <body style="margin:0;padding:30px 14px;background:${rp.base};">
    <table role="presentation" width="100%" style="max-width:600px;margin:0 auto;border-collapse:collapse;">
      <tr>
        <td style="background:${rp.surface};border:1px solid ${rp.overlay};border-radius:8px;overflow:hidden;">
          <table role="presentation" width="100%" style="border-collapse:collapse;">
            <tr><td style="height:3px;line-height:3px;font-size:0;background:${accent};">&nbsp;</td></tr>
            <tr>
              <td style="padding:26px 30px 4px 30px;">
                <div style="font-family:${mono};font-size:11px;color:${rp.pine};">$ systemctl list-timers 'restic-*' &amp;&amp; zpool list</div>
                <div style="font-family:${mono};font-size:22px;font-weight:700;letter-spacing:0.05em;color:${rp.text};margin-top:14px;">BACKUP_AND_STORAGE</div>
                <div style="font-family:${mono};font-size:13px;font-weight:700;color:${accent};margin-top:9px;">${tag[overall]} ${overallCopy}</div>
                <div style="font-family:${mono};font-size:11px;color:${rp.muted};margin-top:9px;">${timestamp} &middot; inari &middot; weekly</div>
              </td>
            </tr>

            ${heading('backup sets', 'restic timers, last trigger')}
            <tr>
              <td style="padding:14px 25px 4px 25px;">
                <table role="presentation" width="100%" style="border-collapse:collapse;table-layout:fixed;">
                  <tr>${sets.map(setCard).join('')}</tr>
                </table>
              </td>
            </tr>
            ${repoLine}

            ${heading('pool capacity', 'growth measured over 7 days')}
            ${poolPanel}

            <tr><td style="border-top:1px solid ${rp.overlay};"></td></tr>
            <tr>
              <td style="padding:14px 30px;font-family:${mono};font-size:10px;color:${rp.muted};line-height:1.6;">
                anything under /raid5pool is outside impermanence and the local restic sets &mdash;
                only the explicit yomi.restic.offsite.paths are copied off-site.
              </td>
            </tr>
          </table>
        </td>
      </tr>
    </table>
  </body>
</html>`;
// }}}

return [{json: {subject: `[inari] ${tag[overall]} backup & storage · ${overallCopy}`, html}}];
